    numero_predial character varying(30),
    numero_predial_anterior character varying(20),
    nupre character varying(11),
    circulo_registral character varying(4),
    matricula_inmobiliaria_catastro character varying(80),
    tipo_predio character varying(100),
    condicion_predio bigint,
    destinacion_economica character varying(150),
    sistema_procedencia_datos bigint,
    fecha_datos date NOT NULL
);


--
-- Name: TABLE gc_prediocatastro; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON TABLE lev_cat_12.gc_prediocatastro IS 'Información existente en las bases de datos catastrales respecto de los predios en una entidad territorial.';


--
-- Name: COLUMN gc_prediocatastro.tipo_catastro; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.tipo_catastro IS 'Indica si el predio se encuentra en catastro fiscal o Ley 14.';


--
-- Name: COLUMN gc_prediocatastro.numero_predial; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.numero_predial IS 'Código numérico de 30 dígitos que permita localizarlo inequívocamente en los respectivos documentos catastrales, según el modelo determinado por el Instituto Geográfico Agustín Codazzi.';


--
-- Name: COLUMN gc_prediocatastro.numero_predial_anterior; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.numero_predial_anterior IS 'Código numérico de 20 dígitos que permita localizarlo inequívocamente en los respectivos documentos catastrales, según el modelo determinado por el Instituto Geográfico Agustín Codazzi.';


--
-- Name: COLUMN gc_prediocatastro.nupre; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.nupre IS 'Es un código único para identificar los inmuebles tanto en los sistemas de información catastral como registral. El NUPRE no implicará supresión de la numeración catastral ni registral asociada a la cédula catastral ni a la matrícula inmobiliaria actual.';


--
-- Name: COLUMN gc_prediocatastro.circulo_registral; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.circulo_registral IS 'Circulo registral al que se encuentra inscrito el predio.';


--
-- Name: COLUMN gc_prediocatastro.matricula_inmobiliaria_catastro; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.matricula_inmobiliaria_catastro IS 'Identificador único asignado por las oficinas de registro de instrumentos públicos.';


--
-- Name: COLUMN gc_prediocatastro.tipo_predio; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.tipo_predio IS 'Tipo de predio inscrito en catastro: Nacional, Departamental, Municipal, Particular, Baldío, Ejido, Resguardo Indígena, Tierra de comunidades negras y Reservas Naturales.';


--
-- Name: COLUMN gc_prediocatastro.condicion_predio; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.condicion_predio IS 'Caracterización temática del predio.';


--
-- Name: COLUMN gc_prediocatastro.destinacion_economica; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.destinacion_economica IS 'Es la clasificación para fines estadísticos que se da a cada inmueble en su conjunto–terreno, construcciones o edificaciones-, en el momento de la identificación predial de conformidad con la actividad predominante que en él se desarrolle.';


--
-- Name: COLUMN gc_prediocatastro.sistema_procedencia_datos; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.sistema_procedencia_datos IS 'Indica el sistema de gestión catastral de donde proceden los datos, en el caso del IGAC puede ser COBOL o SNC.';


--
-- Name: COLUMN gc_prediocatastro.fecha_datos; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.gc_prediocatastro.fecha_datos IS 'Fecha de la vigencia de los datos.';


