-- Name: snr_restriccion; Type: TABLE; Schema: lev_cat_12; Owner: -
--

CREATE TABLE lev_cat_12.snr_restriccion (
    t_id bigint DEFAULT nextval('lev_cat_12.t_ili2db_seq'::regclass) NOT NULL,
    t_basket bigint NOT NULL,
    t_ili_tid character varying(200),
    tipo_restriccion bigint,
    codigo_naturaleza_juridica character varying(5),
    snr_predio bigint
);


--
-- Name: TABLE snr_restriccion; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON TABLE lev_cat_12.snr_restriccion IS 'Es una prohibición específica relacionada con un predio.';


--
-- Name: COLUMN snr_restriccion.tipo_restriccion; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.snr_restriccion.tipo_restriccion IS 'Con los tipos de restricciones de acuerdo con la naturaleza del registro colombiano.';


--
-- Name: COLUMN snr_restriccion.codigo_naturaleza_juridica; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON COLUMN lev_cat_12.snr_restriccion.codigo_naturaleza_juridica IS 'Es el número asignado en el registro a cada acto sujeto a registro.';


--
-- Name: snr_restriccion_titular; Type: TABLE; Schema: lev_cat_12; Owner: -
--

CREATE TABLE lev_cat_12.snr_restriccion_titular (
    t_id bigint DEFAULT nextval('lev_cat_12.t_ili2db_seq'::regclass) NOT NULL,
    t_basket bigint NOT NULL,
    snr_restriccion bigint NOT NULL,
    snr_titular bigint NOT NULL
);


--
-- Name: snr_restricciontipo; Type: TABLE; Schema: lev_cat_12; Owner: -
--

CREATE TABLE lev_cat_12.snr_restricciontipo (
    t_id bigint DEFAULT nextval('lev_cat_12.t_ili2db_seq'::regclass) NOT NULL,
    thisclass character varying(1024) NOT NULL,
    baseclass character varying(1024),
    itfcode integer NOT NULL,
    ilicode character varying(1024) NOT NULL,
    seq integer,
    inactive boolean NOT NULL,
    dispname character varying(250) NOT NULL,
    description text
);


--
-- Name: snr_titular; Type: TABLE; Schema: lev_cat_12; Owner: -
--

CREATE TABLE lev_cat_12.snr_titular (
    t_id bigint DEFAULT nextval('lev_cat_12.t_ili2db_seq'::regclass) NOT NULL,
    t_basket bigint NOT NULL,
    t_ili_tid character varying(200),
    tipo_persona bigint,
    tipo_documento bigint,
    numero_documento character varying(50) NOT NULL,
    nombres character varying(500),
    primer_apellido character varying(255),
    segundo_apellido character varying(255),
    razon_social character varying(255)
);


--
-- Name: TABLE snr_titular; Type: COMMENT; Schema: lev_cat_12; Owner: -
--

COMMENT ON TABLE lev_cat_12.snr_titular IS 'Datos de titulares de derecho inscritos en la SNR.';


